using System;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "EndOfTurnForEndTurnConditionOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/EndOfTurnForEndTurnConditionOmenData")]
public class EndOfTurnForEndTurnConditionOmenData : EndOfTurnOmenData
{
	[NonSerialized]
	private EndTurnConditionSpecificDiceTierOmenData endTurnConditionSpecificDiceTierOmenData;

	[NonSerialized]
	private EndTurnConditionOmenData endTurnConditionOmenData;

	public void InitializeExternal(EndTurnConditionSpecificDiceTierOmenData endTurnConditionSpecificDiceTierOmenData)
	{
		this.endTurnConditionSpecificDiceTierOmenData = endTurnConditionSpecificDiceTierOmenData;
	}

	public void InitializeExternal(EndTurnConditionOmenData endTurnConditionOmenData)
	{
		this.endTurnConditionOmenData = endTurnConditionOmenData;
	}

	protected override Action GetOmenCheckActivationAction(OmenInstance omenInstance)
	{
		return delegate
		{
			if (endTurnConditionSpecificDiceTierOmenData != null)
			{
				if (!endTurnConditionSpecificDiceTierOmenData.AlreadyUsed)
				{
					ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.EndOfTurnOmenActions.Add(GetOmenAction(omenInstance));
				}
			}
			else if (!endTurnConditionOmenData.AlreadyUsed)
			{
				ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.EndOfTurnOmenActions.Add(GetOmenAction(omenInstance));
			}
		};
	}

	public override Action GetOmenAction(OmenInstance omenInstance)
	{
		return delegate
		{
			if (endTurnConditionSpecificDiceTierOmenData != null)
			{
				endTurnConditionSpecificDiceTierOmenData.ActivateBattleAction();
			}
			else
			{
				endTurnConditionOmenData.ActivateBattleAction();
			}
		};
	}
}
